"use strict";(self.webpackChunkshareme=self.webpackChunkshareme||[]).push([["7184"],{16986(n){n.exports=JSON.parse('{"tag":{"label":"wecon","permalink":"/shareme/plc/tags/wecon","allTagsPath":"/shareme/plc/tags","count":29,"items":[{"id":"wecon/01-execution-of-program","title":"01 Execution of the Program: Chu k\u1EF3 qu\xe9t & Th\u1EE9 t\u1EF1 th\u1EF1c thi","description":"Nguy\xean l\xfd chu k\u1EF3 qu\xe9t (Scan Cycle), th\u1EDDi gian x\u1EED l\xfd v\xf2ng l\u1EB7p v\xe0 th\u1EE9 t\u1EF1 th\u1EF1c thi ch\u01B0\u01A1ng tr\xecnh trong PLC Wecon LX6V.","permalink":"/shareme/plc/wecon/01-execution-of-program"},{"id":"wecon/02-devices","title":"02 Devices: B\u1EA3n \u0111\u1ED3 thi\u1EBFt b\u1ECB & V\xf9ng nh\u1EDB","description":"B\u1EA3n \u0111\u1ED3 v\xe0 ph\xe2n lo\u1EA1i v\xf9ng nh\u1EDB thi\u1EBFt b\u1ECB tr\xean PLC Wecon: X, Y, M, S, SM, T, C, D, R, SD.","permalink":"/shareme/plc/wecon/02-devices"},{"id":"wecon/03-sequence-control","title":"03 Sequence Control: \u0110i\u1EC1u khi\u1EC3n tu\u1EA7n t\u1EF1 SFC / STL","description":"K\u1EF9 thu\u1EADt l\u1EADp tr\xecnh \u0111i\u1EC1u khi\u1EC3n qu\xe1 tr\xecnh tu\u1EA7n t\u1EF1 SFC / STL tr\xean PLC Wecon.","permalink":"/shareme/plc/wecon/03-sequence-control"},{"id":"wecon/04-program-flow","title":"04 Program Flow: \u0110i\u1EC1u khi\u1EC3n lu\u1ED3ng ch\u01B0\u01A1ng tr\xecnh","description":"C\xe1c l\u1EC7nh r\u1EBD nh\xe1nh c\xf3 \u0111i\u1EC1u ki\u1EC7n, g\u1ECDi ch\u01B0\u01A1ng tr\xecnh con v\xe0 v\xf2ng l\u1EB7p trong PLC Editor 2.","permalink":"/shareme/plc/wecon/04-program-flow"},{"id":"wecon/05-timer-and-counter","title":"05 Timer and Counter: B\u1ED9 \u0111\u1ECBnh th\u1EDDi & B\u1ED9 \u0111\u1EBFm","description":"H\u01B0\u1EDBng d\u1EABn s\u1EED d\u1EE5ng Timer v\xe0 Counter \u0111\u1ED9 ch\xednh x\xe1c cao tr\xean PLC Wecon.","permalink":"/shareme/plc/wecon/05-timer-and-counter"},{"id":"wecon/06-basic-instructions","title":"06 Basic instructions: T\u1EADp l\u1EC7nh logic c\u01A1 b\u1EA3n","description":"T\u1EADp h\u1EE3p c\xe1c l\u1EC7nh ti\u1EBFp \u0111i\u1EC3m logic, cu\u1ED9n d\xe2y ng\xf5 ra v\xe0 l\u1EC7nh s\u01B0\u1EDDn xung c\u01A1 b\u1EA3n.","permalink":"/shareme/plc/wecon/06-basic-instructions"},{"id":"wecon/07-ethercat","title":"07 EtherCAT: M\u1EA1ng truy\u1EC1n th\xf4ng c\xf4ng nghi\u1EC7p th\u1EDDi gian th\u1EF1c","description":"H\u01B0\u1EDBng d\u1EABn thi\u1EBFt l\u1EADp v\xe0 c\u1EA5u h\xecnh m\u1EA1ng truy\u1EC1n th\xf4ng Bus EtherCAT cho Servo Drive tr\xean Wecon LX6V.","permalink":"/shareme/plc/wecon/07-ethercat"},{"id":"wecon/motion-control/tong-quan-chuong-08-motion-control","title":"08 Motion Control - T\u1ED5ng quan \u0110i\u1EC1u khi\u1EC3n Chuy\u1EC3n \u0111\u1ED9ng","description":"T\u1ED5ng quan ki\u1EBFn tr\xfac \u0111i\u1EC1u khi\u1EC3n chuy\u1EC3n \u0111\u1ED9ng, m\xf4 h\xecnh tr\u1EE5c logic v\xe0 c\xe1c nh\xf3m kh\u1ED1i h\xe0m trong Ch\u01B0\u01A1ng 08 Motion Control tr\xean PLC Wecon LX6V / LX6A.","permalink":"/shareme/plc/wecon/motion-control/"},{"id":"wecon/09-high-speed-counter","title":"09 High Speed Counter: B\u1ED9 \u0111\u1EBFm xung t\u1ED1c \u0111\u1ED9 cao ph\u1EA7n c\u1EE9ng","description":"C\u1EA5u h\xecnh b\u1ED9 \u0111\u1EBFm t\u1ED1c \u0111\u1ED9 cao HSC \u0111\u1ECDc Encoder 1 pha, 2 pha AB tr\xean PLC Wecon.","permalink":"/shareme/plc/wecon/09-high-speed-counter"},{"id":"wecon/10-communication-instruction","title":"10 Communication Instruction: Truy\u1EC1n th\xf4ng n\u1ED1i ti\u1EBFp Modbus","description":"T\u1EADp l\u1EC7nh truy\u1EC1n th\xf4ng n\u1ED1i ti\u1EBFp RS-485 / RS-422 qua Modbus RTU / ASCII.","permalink":"/shareme/plc/wecon/10-communication-instruction"},{"id":"wecon/11-pid-control-instruction","title":"11 PID Control Instruction: Thu\u1EADt to\xe1n \u0111i\u1EC1u khi\u1EC3n v\xf2ng k\xedn","description":"L\u1EADp tr\xecnh \u0111i\u1EC1u khi\u1EC3n v\xf2ng k\xedn nhi\u1EC7t \u0111\u1ED9, \xe1p su\u1EA5t PID v\u1EDBi t\xednh n\u0103ng Auto-tuning.","permalink":"/shareme/plc/wecon/11-pid-control-instruction"},{"id":"wecon/12-character-string-instruction","title":"12 Character String Instruction: X\u1EED l\xfd chu\u1ED7i k\xfd t\u1EF1 ASCII","description":"T\u1EADp l\u1EC7nh thao t\xe1c chu\u1ED7i k\xfd t\u1EF1, gh\xe9p chu\u1ED7i, t\xe1ch chu\u1ED7i v\xe0 chuy\u1EC3n \u0111\u1ED5i ki\u1EC3u d\u1EEF li\u1EC7u.","permalink":"/shareme/plc/wecon/12-character-string-instruction"},{"id":"wecon/13-ethernet-communication","title":"13 Ethernet Communication: Truy\u1EC1n th\xf4ng m\u1EA1ng LAN & Socket","description":"C\u1EA5u h\xecnh c\u1ED5ng m\u1EA1ng Ethernet t\xedch h\u1EE3p tr\xean PLC Wecon LX6V: Modbus TCP, Socket TCP/UDP.","permalink":"/shareme/plc/wecon/13-ethernet-communication"},{"id":"wecon/14-builtin-fc-fb","title":"14 Built-in FC/FB: Th\u01B0 vi\u1EC7n kh\u1ED1i h\xe0m m\u1EDF r\u1ED9ng t\xedch h\u1EE3p","description":"Danh m\u1EE5c c\xe1c h\xe0m (FC) v\xe0 kh\u1ED1i h\xe0m (FB) \u0111\u1ECBnh ngh\u0129a s\u1EB5n trong PLC Editor 2.","permalink":"/shareme/plc/wecon/14-builtin-fc-fb"},{"id":"wecon/15-st-help-manual","title":"15 ST Help Manual: S\u1ED5 tay ng\xf4n ng\u1EEF Structured Text (ST)","description":"C\u1EA9m nang c\xfa ph\xe1p, to\xe1n t\u1EED v\xe0 c\u1EA5u tr\xfac l\u1EADp tr\xecnh ng\xf4n ng\u1EEF Structured Text IEC 61131-3.","permalink":"/shareme/plc/wecon/15-st-help-manual"},{"id":"wecon/motion-control/8.01-management-function-blocks-single-axis","title":"8.01 Kh\u1ED1i h\xe0m qu\u1EA3n tr\u1ECB \u0111i\u1EC1u khi\u1EC3n \u0111\u01A1n tr\u1EE5c (Management FBs)","description":"H\u01B0\u1EDBng d\u1EABn k\u1EF9 thu\u1EADt chi ti\u1EBFt 13 kh\u1ED1i h\xe0m qu\u1EA3n tr\u1ECB \u0111\u01A1n tr\u1EE5c chu\u1EA9n PLCopen tr\xean PLC Wecon LX6V / LX6A500: MC_POWER, MC_READSTATUS, MC_RESET, MC_TouchProbe...","permalink":"/shareme/plc/wecon/motion-control/8.01-management-function-blocks-single-axis"},{"id":"wecon/motion-control/8.02-motion-function-blocks-single-axis","title":"8.02 Kh\u1ED1i h\xe0m chuy\u1EC3n \u0111\u1ED9ng \u0111i\u1EC1u khi\u1EC3n \u0111\u01A1n tr\u1EE5c (Motion FBs)","description":"H\u01B0\u1EDBng d\u1EABn k\u1EF9 thu\u1EADt chi ti\u1EBFt 7 kh\u1ED1i h\xe0m chuy\u1EC3n \u0111\u1ED9ng \u0111\u01A1n tr\u1EE5c: MC_STOP, MC_HOME, MC_HALT, MC_MOVEABSOLUTE, MC_MOVERELATIVE, MC_MOVEADDITIVE, MC_MOVESUPERIMPOSED.","permalink":"/shareme/plc/wecon/motion-control/8.02-motion-function-blocks-single-axis"},{"id":"wecon/motion-control/8.03-management-fb-multi-axis","title":"8.03 Kh\u1ED1i h\xe0m qu\u1EA3n tr\u1ECB \u0111i\u1EC1u khi\u1EC3n \u0111a tr\u1EE5c (Multi-axis Management FBs)","description":"H\u01B0\u1EDBng d\u1EABn k\u1EF9 thu\u1EADt 3 kh\u1ED1i h\xe0m qu\u1EA3n tr\u1ECB b\u1EA3ng d\u1EEF li\u1EC7u Cam \u0111i\u1EC7n t\u1EED (E-CAM): MC_CAMTABLESELECT, MC_GENERATECAMTABLE, MC_SAVECAMTABLE.","permalink":"/shareme/plc/wecon/motion-control/8.03-management-fb-multi-axis"},{"id":"wecon/motion-control/8.04-motion-fb-multi-axis","title":"8.04 Kh\u1ED1i h\xe0m chuy\u1EC3n \u0111\u1ED9ng \u0111i\u1EC1u khi\u1EC3n \u0111a tr\u1EE5c (Multi-axis Motion FBs)","description":"H\u01B0\u1EDBng d\u1EABn chi ti\u1EBFt 5 kh\u1ED1i h\xe0m kh\u1EDBp n\u1ED1i v\xe0 \u0111\u1ED3ng b\u1ED9 chuy\u1EC3n \u0111\u1ED9ng \u0111a tr\u1EE5c: MC_CAMIN, MC_CAMOUT, MC_GEARIN, MC_GEAROUT, MC_GEARINPOS tr\xean PLC Wecon.","permalink":"/shareme/plc/wecon/motion-control/8.04-motion-fb-multi-axis"},{"id":"wecon/motion-control/8.05-management-functions-axis-group","title":"8.05 Kh\u1ED1i h\xe0m qu\u1EA3n tr\u1ECB \u0111i\u1EC1u khi\u1EC3n nh\xf3m tr\u1EE5c (Axis Group Management)","description":"H\u01B0\u1EDBng d\u1EABn k\u1EF9 thu\u1EADt 10 kh\u1ED1i h\xe0m qu\u1EA3n tr\u1ECB nh\xf3m tr\u1EE5c (Axis Group) cho c\xe1c c\u01A1 c\u1EA5u nhi\u1EC1u b\u1EADc t\u1EF1 do (Cartesian, Delta, SCARA, CNC) tr\xean PLC Wecon.","permalink":"/shareme/plc/wecon/motion-control/8.05-management-functions-axis-group"},{"id":"wecon/motion-control/8.06-axis-group-motion-fb","title":"8.06 Kh\u1ED1i h\xe0m chuy\u1EC3n \u0111\u1ED9ng nh\xf3m tr\u1EE5c (Axis Group Motion FBs)","description":"H\u01B0\u1EDBng d\u1EABn k\u1EF9 thu\u1EADt 8 kh\u1ED1i h\xe0m n\u1ED9i suy nh\xf3m tr\u1EE5c: N\u1ED9i suy \u0111\u01B0\u1EDDng th\u1EB3ng (Linear), n\u1ED9i suy cung tr\xf2n (Circular) 3 ch\u1EBF \u0111\u1ED9, ch\u1EA1y tr\u1EF1c ti\u1EBFp (Direct) tr\xean Wecon.","permalink":"/shareme/plc/wecon/motion-control/8.06-axis-group-motion-fb"},{"id":"wecon/motion-control/8.07-other-special-fb","title":"8.07 C\xe1c kh\u1ED1i h\xe0m chuy\u1EC3n \u0111\u1ED9ng \u0111\u1EB7c bi\u1EC7t kh\xe1c (Other Special FBs)","description":"H\u01B0\u1EDBng d\u1EABn k\u1EF9 thu\u1EADt chi ti\u1EBFt 10 kh\u1ED1i h\xe0m \u0111\u1EB7c bi\u1EC7t: MC_MOVEJOG, MC_MOVEVELOCITY, MC_COMBINEAXES, Torque Control v\xe0 c\xe1c ch\u1EBF \u0111\u1ED9 CiA402 CSV/PV/PT/PP.","permalink":"/shareme/plc/wecon/motion-control/8.07-other-special-fb"},{"id":"wecon/motion-control/8.08-sdo-instruction","title":"8.08 L\u1EC7nh truy\u1EC1n th\xf4ng SDO qua m\u1EA1ng Bus EtherCAT","description":"H\u01B0\u1EDBng d\u1EABn chi ti\u1EBFt c\xfa ph\xe1p v\xe0 c\xe1ch th\u1EE9c \u0111\u1ECDc/ghi tham s\u1ED1 t\u1EEB \u0111i\u1EC3n \u0111\u1ED1i t\u01B0\u1EE3ng (Object Dictionary) c\u1EE7a Servo Drive qua l\u1EC7nh SDO: MC_READSDO v\xe0 MC_WRITESDO.","permalink":"/shareme/plc/wecon/motion-control/8.08-sdo-instruction"},{"id":"wecon/motion-control/8.09-built-in-variables-pulse-axis","title":"8.09 Bi\u1EBFn h\u1EC7 th\u1ED1ng t\xedch h\u1EE3p c\u1EE7a tr\u1EE5c ph\xe1t xung n\u1ED9i b\u1ED9","description":"Chi ti\u1EBFt to\xe0n b\u1ED9 b\u1EA3ng bi\u1EBFn h\u1EC7 th\u1ED1ng to\xe0n c\u1EE5c AXIS_INFO_T (Cfg, Cmd, Act, Status, Dbg) v\xe0 \xe1nh x\u1EA1 ph\u1EA7n c\u1EE9ng ch\xe2n ph\xe1t xung Y0-Y7 tr\xean PLC Wecon.","permalink":"/shareme/plc/wecon/motion-control/8.09-built-in-variables-pulse-axis"},{"id":"wecon/motion-control/8.10-others-state-machine-buffermode","title":"8.10 S\u01A1 \u0111\u1ED3 tr\u1EA1ng th\xe1i, Ch\u1EBF \u0111\u1ED9 cung tr\xf2n & V\xf9ng \u0111\u1EC7m BufferMode","description":"Chi ti\u1EBFt to\xe0n di\u1EC7n s\u01A1 \u0111\u1ED3 chuy\u1EC3n \u0111\u1ED5i tr\u1EA1ng th\xe1i PLCopen, 3 ch\u1EBF \u0111\u1ED9 v\u1EBD cung tr\xf2n CircMode v\xe0 6 ch\u1EBF \u0111\u1ED9 v\xf9ng \u0111\u1EC7m BufferMode n\u1ED1i qu\u1EF9 \u0111\u1EA1o kh\xf4ng gi\xe1n \u0111o\u1EA1n.","permalink":"/shareme/plc/wecon/motion-control/8.10-others-state-machine-buffermode"},{"id":"wecon/motion-control/8.11-error-code-table","title":"8.11 B\u1EA3ng tra c\u1EE9u ch\u1EA9n \u0111o\xe1n m\xe3 l\u1ED7i to\xe0n di\u1EC7n (Error Codes)","description":"B\u1EA3ng tra c\u1EE9u \u0111\u1ED1i chi\u1EBFu to\xe0n di\u1EC7n 154 m\xe3 l\u1ED7i Motion Control chu\u1EA9n h\xe3ng Wecon (Run-time, State-machine, Axis error, Servo, SDO) k\xe8m gi\u1EA3i ph\xe1p x\u1EED l\xfd.","permalink":"/shareme/plc/wecon/motion-control/8.11-error-code-table"},{"id":"wecon/motion-control/8.12-chuong-trinh-mau-giang-day","title":"8.12 Khung ch\u01B0\u01A1ng tr\xecnh chu\u1EA9n 5 b\u01B0\u1EDBc ph\u1EE5c v\u1EE5 gi\u1EA3ng d\u1EA1y","description":"Khung ch\u01B0\u01A1ng tr\xecnh m\u1EABu 5 b\u01B0\u1EDBc tu\u1EA7n t\u1EF1 chu\u1EA9n qu\u1ED1c t\u1EBF (C\u1EA5p ngu\u1ED3n, X\xf3a l\u1ED7i, V\u1EC1 g\u1ED1c, \u0110\u1ECBnh v\u1ECB, D\u1EEBng an to\xe0n) b\u1EB1ng ng\xf4n ng\u1EEF Structured Text ph\u1EE5c v\u1EE5 gi\u1EA3ng d\u1EA1y.","permalink":"/shareme/plc/wecon/motion-control/8.12-chuong-trinh-mau-giang-day"},{"id":"wecon/16-appendixes","title":"Appendixes: Ph\u1EE5 l\u1EE5c k\u1EF9 thu\u1EADt & So s\xe1nh d\xf2ng PLC Wecon","description":"B\u1EA3ng tra c\u1EE9u th\xf4ng s\u1ED1 k\u1EF9 thu\u1EADt ph\u1EA7n c\u1EE9ng, k\xedch th\u01B0\u1EDBc \u0111\u1EA5u d\xe2y v\xe0 so s\xe1nh LX6V / LX6S / A500.","permalink":"/shareme/plc/wecon/16-appendixes"},{"id":"wecon/tong-quan-plc-wecon-lx6v-lx6a","title":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt PLC Wecon LX6V / LX6A (PLC Editor 2)","description":"S\u1ED5 tay h\u01B0\u1EDBng d\u1EABn k\u1EF9 thu\u1EADt to\xe0n di\u1EC7n cho d\xf2ng PLC Wecon LX6V / LX6A500 l\u1EADp tr\xecnh tr\xean ph\u1EA7n m\u1EC1m PLC Editor 2 chu\u1EA9n qu\u1ED1c t\u1EBF IEC 61131-3.","permalink":"/shareme/plc/wecon/"}],"unlisted":false}}')}}]);